import type { Cond, Effects, Page, Passage, Story } from '../../src/engine/types';

const is = (flag: string, value: string | boolean = true): Cond => ({ flag, is: value });
const not = (cond: Cond): Cond => ({ not: cond });
const all = (...conds: Cond[]): Cond => ({ all: conds });
const ge = (n: number): Cond => ({ flag: 'lead', gte: n });
const le = (n: number): Cond => ({ flag: 'lead', lte: n });
const cost = (n: number): Effects => ({ add: { lead: -n } });
const coordinated = all(ge(20), is('teamPlan', 'flats'), is('signal', 'timed'), is('slothChoice'), is('slothWith'));

